    set label(value) { this.context.edit(() => this.busBox.label.setValue(Guard.string(value, "label"))); }
    get icon() { return this.busBox.icon.getValue(); }
    set icon(value) { this.context.edit(() => this.busBox.icon.setValue(AudioUnitImpls.validateIcon(value))); }
