import { Arrays, isDefined, panic, tryCatch } from "@opendaw/lib-std";
export class Context {
    #skeleton;
    #facades;
    #samples;
    #tasks;
    #pending;
    #origin;
    constructor(skeleton) {
        this.#skeleton = skeleton;
        this.#facades = new WeakMap();
        this.#samples = new Map();
        this.#tasks = [];
        this.#pending = [];
        this.#origin = null;
    }
    // Records every change from now on, so the studio can replay it onto the graph this one was read from.
    startRecording() {
        this.#origin = this.boxGraph.checksum();
        this.boxGraph.subscribeToAllUpdatesImmediate({ onUpdate: (update) => this.#pending.push(this.#toTask(update)) });
        this.boxGraph.subscribeTransaction({
            onBeginTransaction: () => Arrays.clear(this.#pending),
            onEndTransaction: (rolledBack) => {
                if (!rolledBack) {
                    this.#tasks.push(...this.#pending);
                }
                Arrays.clear(this.#pending);
            }
        });
    }
    get origin() { return this.#origin; }
    takeUpdates() {
        const tasks = this.#tasks.slice();
        Arrays.clear(this.#tasks);
        this.#origin = this.boxGraph.checksum();
        return tasks;
    }
    #toTask(update) {
        switch (update.type) {
            case "new":
                return { type: "new", name: update.name, uuid: update.uuid, buffer: update.settings };
            case "primitive":
                return {
                    type: "update-primitive", address: update.address.decompose(),
                    primitiveType: update.serialization.type, value: update.newValue
                };
            case "pointer":
                return {
                    type: "update-pointer", address: update.address.decompose(),
                    target: update.newAddress.unwrapOrNull()?.decompose()
                };
            case "delete":
                return { type: "delete", uuid: update.uuid };
            default:
                return panic(`Unknown update ${update}`);
        }
    }
    get skeleton() { return this.#skeleton; }
    get samples() { return this.#samples; }
    get boxGraph() { return this.#skeleton.boxGraph; }
    edit(procedure) {
        const boxGraph = this.boxGraph;
        if (boxGraph.inTransaction()) {
            return procedure();
        }
        boxGraph.beginTransaction();
        const result = tryCatch(procedure);
        if (result.status === "failure") {
            boxGraph.abortTransaction();
            throw result.error;
        }
        boxGraph.endTransaction();
        return result.value;
    }
    facade(box, factory) {
        const existing = this.#facades.get(box);
        if (isDefined(existing)) {
            return existing;
        }
        const created = factory(box);
        this.#facades.set(box, created);
        return created;
    }
    optFacade(box) { return this.#facades.get(box); }
}
